// Orda — deterministic maths for the simulation. Math.sin / cos / exp / log2 are "implementation
// approximated" in JavaScript: V8, SpiderMonkey and JavaScriptCore may differ in the last bit, and a
// crowd simulation amplifies that into a different game. The daily challenge is generated by playing
// the level headlessly in the player's own browser, so every browser must compute the same numbers.
// These use only + − × ÷, Math.floor / Math.round / Math.abs (all exact in IEEE 754), so the result
// is bit-identical everywhere. Accuracy ~1e-15 relative, far below anything the game can see.

const PIO2_HI = 1.5707963267341256, PIO2_LO = 6.077100506506192e-11, INV_PIO2 = 0.6366197723675814;
// fdlibm kernels on |x| ≤ π/4
const S1 = -1.66666666666666324348e-01, S2 = 8.33333333332248946124e-03, S3 = -1.98412698298579493134e-04, S4 = 2.75573137070700676789e-06, S5 = -2.50507602534068634195e-08, S6 = 1.58969099521155010221e-10;
const C1 = 4.16666666666666019037e-02, C2 = -1.38888888888741095749e-03, C3 = 2.48015872894767294178e-05, C4 = -2.75573143513906633035e-07, C5 = 2.08757232129817482790e-09, C6 = -1.13596475577881948265e-11;
function ksin(x) { const z = x * x; return x + x * z * (S1 + z * (S2 + z * (S3 + z * (S4 + z * (S5 + z * S6))))); }
function kcos(x) { const z = x * x; return 1 - 0.5 * z + z * z * (C1 + z * (C2 + z * (C3 + z * (C4 + z * (C5 + z * C6))))); }
// quadrant n and reduced argument r = x − n·π/2 (Cody–Waite; fine for the |x| < 1e6 the game uses)
export function dsin(x) {
  if (!Number.isFinite(x)) return NaN;
  const n = Math.round(x * INV_PIO2), r = (x - n * PIO2_HI) - n * PIO2_LO, q = ((n % 4) + 4) % 4;
  return q === 0 ? ksin(r) : q === 1 ? kcos(r) : q === 2 ? -ksin(r) : -kcos(r);
}
export function dcos(x) {
  if (!Number.isFinite(x)) return NaN;
  const n = Math.round(x * INV_PIO2), r = (x - n * PIO2_HI) - n * PIO2_LO, q = ((n % 4) + 4) % 4;
  return q === 0 ? kcos(r) : q === 1 ? -ksin(r) : q === 2 ? -kcos(r) : ksin(r);
}
const LN2_HI = 6.93147180369123816490e-01, LN2_LO = 1.90821492927058770002e-10, INV_LN2 = 1.44269504088896338700;
// e^x: x = k·ln2 + r, |r| ≤ ln2/2, Taylor to r^13 (error < 1e-16), times 2^k by exact doublings
export function dexp(x) {
  if (x !== x) return NaN;
  if (x > 709) return Infinity; if (x < -745) return 0;
  const k = Math.round(x * INV_LN2), r = (x - k * LN2_HI) - k * LN2_LO;
  let t = 1, s = 1;
  for (let i = 1; i <= 13; i++) { t = t * r / i; s += t; }
  return scale2(s, k);
}
function scale2(v, k) { while (k > 0) { v *= 2; k--; } while (k < 0) { v *= 0.5; k++; } return v; }
// log2: x = m·2^e with m in [√½, √2), ln m = 2·atanh(f), f = (m−1)/(m+1), |f| < 0.172
const SQRT2 = 1.4142135623730951, SQRTH = 0.7071067811865476, INV_LN2_LOG = 1.4426950408889634;
export function dlog2(x) {
  if (!(x > 0)) return x === 0 ? -Infinity : NaN;
  if (x === Infinity) return Infinity;
  let e = 0, m = x;
  while (m >= 1024) { m *= 1 / 1024; e += 10; } while (m < 1 / 1024) { m *= 1024; e -= 10; }
  while (m >= SQRT2) { m *= 0.5; e++; } while (m < SQRTH) { m *= 2; e--; }
  const f = (m - 1) / (m + 1), f2 = f * f;
  let t = f, s = 0;
  for (let i = 1; i <= 29; i += 2) { s += t / i; t *= f2; }
  return e + 2 * s * INV_LN2_LOG;
}
